"""Small bundled line icons; decoded by native Toga images, with no runtime imaging dependency."""
from base64 import b64decode
from functools import lru_cache
import toga

ICONS = {
    'archives': '',
    'comic': '',
    'epub': '',
    'text': '',
    'folder_hub': '',
    'files': '',
    'documents': '',
    'books': '',
    'chat': '',
    'markdown': '',
}

@lru_cache(maxsize=12)
def icon(name):
    return toga.Image(src=b64decode(ICONS.get(name, ICONS["documents"])))
